var SCHEMA="TABLE stations -- one row per NEVI-funded station on PennDOT's roster (13 stations; 10 have session data in this release)\n  station_order BIGINT -- 1 = first station to open\n  station_id VARCHAR -- EV-ChART station identifier (text). Join key for every other table\n  awardee VARCHAR -- NEVI awardee / site host (e.g. Pilot Travel Centers, Love's, Tesla Inc.)\n  network_operator VARCHAR -- Charging network: EVgo, ChargePoint, Tesla, Francis Energy\n  address VARCHAR -- Street address\n  city VARCHAR -- City\n  operational_date TIMESTAMP -- Date the station opened\n  om_end_date TIMESTAMP -- End of the 5-year O&M obligation\n  station_name VARCHAR -- Short town name used throughout the dashboard, e.g. 'Pittston'. Prefer this in answers\n  lat DOUBLE -- Latitude (from PennDOT's award inventory)\n  lon DOUBLE -- Longitude\n  interstate VARCHAR -- Nearest Alternative Fuel Corridor interstate\n  n_ports BIGINT -- Number of charging ports (all stations have 4)\n  first_session_date TIMESTAMP -- First session in the data\n  last_session_date TIMESTAMP -- Last session in the data\n  has_session_data BOOLEAN -- FALSE for stations that opened after the data cut-off (Mifflinville, New Castle, Brookville)\n  funding_round VARCHAR -- NEVI funding round, e.g. 'AFC Round 1'\n  highway VARCHAR -- Highway(s) served\n  exit VARCHAR -- Exit number(s)\n  county VARCHAR -- County\n  award_amount DOUBLE -- NEVI award in US dollars\n  penndot_district BIGINT -- PennDOT engineering district (1-12)\nTABLE awarded_stations -- one row per NEVI/AFC award site in PennDOT's program inventory (GIS export of Oct 29, 2026; 207 sites). Inventory only - no usage data. Only rows with has_session_data = TRUE (10 sites) have charging data in the other tables, and that data ends 2025-03-31\n  award_id BIGINT -- Row id\n  station_id VARCHAR -- Links to stations.station_id for the 13 roster stations; NULL otherwise\n  has_session_data BOOLEAN -- TRUE when session/uptime data exists in this dashboard\n  organization_name VARCHAR -- Awardee / operator organization\n  site_host VARCHAR -- Host business (e.g. Sheetz, Wawa)\n  city VARCHAR\n  county VARCHAR\n  latitude DOUBLE\n  longitude DOUBLE\n  funding_round VARCHAR -- 'AFC Round 1', 'AFC Round 1A', 'AFC Round 1B', 'Corridor Connections', 'Community - Southeastern', 'EVC-RAA Round 1', 'EVC-RAA Round 1A', or 'AFC Creditable' (existing NEVI-compliant station counted toward corridor build-out, no NEVI award)\n  project_type VARCHAR -- 'Highway Corridor', 'Community - DC Fast', 'Community - Level 2'\n  status VARCHAR -- 'Operational', 'In Progress', 'Planned'\n  highway VARCHAR\n  exit VARCHAR\n  nevi_dc_ports BIGINT -- NEVI-funded DC fast ports\n  total_dc_ports BIGINT -- All DC fast ports at the site\n  nevi_l2_ports BIGINT -- NEVI-funded Level 2 ports\n  total_l2_ports BIGINT -- All Level 2 ports\n  award_amount DOUBLE -- US dollars; NULL for AFC Creditable sites\n  electric_distribution_company VARCHAR -- Utility\n  penndot_district BIGINT -- PennDOT engineering district\n  planning_partner VARCHAR -- MPO/RPO\n  notes VARCHAR\nTABLE daily_station -- one row per station per local calendar day (America/New_York), from opening through its last reported day; zero-session days included\n  station_id VARCHAR\n  date TIMESTAMP -- Local date\n  sessions_total BIGINT -- All sessions attempted\n  sessions_success BIGINT -- Successful sessions (see rule)\n  energy_kwh DOUBLE -- kWh delivered by successful sessions\n  avg_energy_kwh DOUBLE -- Mean kWh per successful session\n  avg_power_kw DOUBLE -- Mean of session average power (kW)\n  avg_duration_min DOUBLE -- Mean plug-in duration (min)\n  ports_used BIGINT -- Distinct ports with a successful session\n  sessions_failed BIGINT -- sessions_total - sessions_success\n  busy_port_minutes DOUBLE -- Sum over ports of minutes occupied by a successful session\n  all_ports_busy_minutes DOUBLE -- Minutes in the day when every port was occupied (queue risk)\n  peak_concurrent BIGINT -- Max ports simultaneously in use\n  outage_port_minutes DOUBLE -- Sum over ports of reported outage minutes that day (no exclusions)\n  n_ports BIGINT\n  port_utilization DOUBLE -- busy_port_minutes / (n_ports * 1440), 0-1\n  month TIMESTAMP -- First day of month (timestamp)\n  quarter VARCHAR -- e.g. '2025Q1'\nTABLE monthly_port -- one row per port per month from the station's opening month\n  station_id VARCHAR\n  port_label VARCHAR -- P1..P4 (stable within a station)\n  month TIMESTAMP -- First day of month\n  sessions_total BIGINT\n  sessions_success BIGINT\n  energy_kwh DOUBLE\n  busy_minutes DOUBLE -- Minutes in use\n  outage_minutes DOUBLE -- Reported outage minutes (Module 4), split across days, no exclusions\n  outage_events BIGINT -- Outage events starting this month\n  minutes_in_service DOUBLE -- Minutes the port was in service this month (partial first month)\n  uptime_pct DOUBLE -- Raw monthly availability = 100*(1 - outage_minutes/minutes_in_service). Does NOT apply NEVI excluded outages, so it is a conservative lower bound\nTABLE port_uptime_reported -- one row per port: the latest cumulative Module 3 uptime report\n  station_id VARCHAR\n  port_label VARCHAR\n  reporting_start TIMESTAMP\n  reporting_end TIMESTAMP\n  reported_uptime_pct DOUBLE -- Operator-reported 12-month uptime; NULL when the port has < 1 year of history\n  total_outage_min DOUBLE -- Cumulative outage minutes since reporting_start\n  excluded_outage_min DOUBLE -- Outage minutes excluded under 23 CFR 680.116 (utility outage, vandalism, etc.)\n  uptime_since_start_pct DOUBLE -- 100*(1 - (total_outage_min - excluded_outage_min)/minutes since reporting_start). NEVI formula applied to the whole period since the port's first report\n  uptime_nevi_pct DOUBLE -- Compliance figure to use: the operator-reported 12-month uptime when available, otherwise uptime_since_start_pct\nTABLE outage_events -- one row per reported outage event per port\n  station_id VARCHAR\n  port_label VARCHAR\n  start_date TIMESTAMP -- Local start date\n  end_date TIMESTAMP -- Local end date\n  duration_min DOUBLE\n  duration_hours DOUBLE\nTABLE quarterly_station -- one row per station per quarter, computed from the raw submissions by this pipeline\n  station_id VARCHAR\n  quarter VARCHAR\n  sessions_total BIGINT\n  sessions_success BIGINT\n  energy_kwh DOUBLE\n  avg_energy_kwh DOUBLE\n  median_power_kw DOUBLE\n  avg_duration_min DOUBLE\n  days_in_service BIGINT\n  port_utilization DOUBLE -- Mean daily port utilization 0-1\n  all_ports_busy_minutes DOUBLE\n  outage_port_minutes DOUBLE\n  sessions_failed BIGINT\n  success_rate DOUBLE -- 0-1\n  sessions_per_day DOUBLE -- Successful sessions per day in service\n  uptime_pct_raw DOUBLE -- Raw quarterly availability across all ports, no exclusions\nTABLE quarterly_reported -- one row per station per quarter, exactly as reported in PennDOT's quarterly summary workbook\n  station_id VARCHAR\n  quarter VARCHAR\n  operating_days BIGINT\n  rolling_12mo_uptime_pct DOUBLE -- PennDOT-reported 12-month rolling uptime (%)\n  sessions_success BIGINT\n  sessions_failed BIGINT\n  success_rate DOUBLE -- 0-1\n  energy_kwh DOUBLE\nTABLE hourly_profile -- successful sessions by station, quarter, day of week, and local start hour\n  station_id VARCHAR\n  quarter VARCHAR\n  day_of_week INTEGER -- 0=Monday ... 6=Sunday\n  hour INTEGER -- Local start hour 0-23\n  sessions BIGINT\n  energy_kwh DOUBLE\nTABLE failures_quarterly -- failed sessions by station, quarter, and failure type\n  station_id VARCHAR\n  quarter VARCHAR\n  failure_type VARCHAR -- ChargeX error code (CX002, CX009, ...), 'other', 'Corrupted', or 'no_error_but_<1kWh' (session ended with no error code but delivered < 1 kWh)\n  sessions BIGINT\nTABLE payments_quarterly -- successful sessions by station, quarter, and payment method\n  station_id VARCHAR\n  quarter VARCHAR\n  payment_method VARCHAR -- credit_card_terminal, phone_online, membership, roaming, other, none\n  sessions BIGINT\nTABLE session_distribution -- histogram of successful sessions per station; one row per (station, metric, bin)\n  station_id VARCHAR\n  metric VARCHAR -- 'energy_kwh' | 'power_kw' | 'duration_min'\n  bin_lo DOUBLE -- inclusive\n  bin_hi DOUBLE -- exclusive\n  sessions BIGINT\n  is_top_bin BOOLEAN -- TRUE for the last bin, which also holds every value above it\n\nSTATIONS: Pittston (EVgo); Emlenton (ChargePoint); Aston (Tesla); Jonestown (ChargePoint); Slippery Rock (ChargePoint); Chambersburg (Francis Energy); Carlisle (Francis Energy); New Milford (EVgo); Mill Hall (EVgo); Kylertown (Francis Energy); Mifflinville (ChargePoint, no data yet); New Castle (Tesla, no data yet); Brookville (ChargePoint, no data yet)\n\nRULES:\n- Charging data covers 2023-12-22 to 2025-03-31 (EV-ChART quarterly submissions through 2025 Q1) for 10 stations. Say so if a question asks about later dates or other stations.\n- awarded_stations is the program inventory (207 award sites, status as of Oct 2026). Use it for questions about awards, funding, counts by status/round/county/district; it has no usage data.\n- Successful session = no error code AND >= 1 kWh delivered. Failed = everything else.\n- NEVI uptime requirement (23 CFR 680.116): each port >= 97% over a trailing 12 months, with excluded outages removed. Use port_uptime_reported.uptime_nevi_pct for compliance; monthly_port.uptime_pct is a raw lower bound.\n- NEVI minimum power: 150 kW per port simultaneously. Session power is limited by the vehicle as well as the charger, so median session power below 150 kW is NOT by itself a violation.\n- Tesla (Aston) reports zero failed sessions - Tesla's submission appears not to include failures; flag this when comparing reliability.\n- Scales: *_pct columns are 0-100 (97% is written 97, never 0.97); *_rate columns and port_utilization are 0-1 fractions.\n- Always join to stations to show station_name; never show raw station_id alone.\n- Quarters are strings like '2025Q1'. Months are timestamps at the first of the month.\n- Session-level records are NOT available - only these aggregates. Do not invent columns.\n\nEXAMPLES:\nQ: Which ports are below the 97% uptime requirement?\nSQL:\nSELECT s.station_name, p.port_label, p.uptime_nevi_pct, p.reporting_start, p.reporting_end\nFROM port_uptime_reported p JOIN stations s USING (station_id)\nWHERE p.uptime_nevi_pct < 97 ORDER BY p.uptime_nevi_pct\n\nQ: Monthly successful sessions statewide\nSQL:\nSELECT month, SUM(sessions_success) AS sessions FROM daily_station GROUP BY month ORDER BY month\n\nQ: What are the main failure causes at Francis Energy stations?\nSQL:\nSELECT s.station_name, f.failure_type, SUM(f.sessions) AS sessions\nFROM failures_quarterly f JOIN stations s USING (station_id)\nWHERE s.network_operator = 'Francis Energy' GROUP BY ALL ORDER BY s.station_name, sessions DESC\n\nQ: How many awarded sites are operational in each funding round, and how much was awarded?\nSQL:\nSELECT funding_round, COUNT(*) AS sites, COUNT(*) FILTER (WHERE status = 'Operational') AS operational,\n  SUM(award_amount) AS award_usd FROM awarded_stations GROUP BY ALL ORDER BY sites DESC\n\nQ: Busiest hour of the week at Aston\nSQL:\nSELECT day_of_week, hour, SUM(sessions) AS sessions FROM hourly_profile h JOIN stations s USING (station_id)\nWHERE s.station_name = 'Aston' GROUP BY ALL ORDER BY sessions DESC LIMIT 5";var DEFAULT_MODEL="@cf/openai/gpt-oss-120b";var WORKERS_AI_MODELS=["@cf/meta/llama-3.3-70b-instruct-fp8-fast","@cf/openai/gpt-oss-120b","@cf/qwen/qwen2.5-coder-32b-instruct","@cf/deepseek-ai/deepseek-v4-flash-0731","@cf/meta/llama-4-scout-17b-16e-instruct","@cf/mistralai/mistral-small-3.1-24b-instruct","@cf/zai-org/glm-4.7-flash","@cf/qwen/qwen3-30b-a3b-fp8"];var SQL_SYSTEM=`You translate questions about Pennsylvania NEVI electric-vehicle charging stations into a single DuckDB SQL query.

${SCHEMA}

Instructions:
- Return ONLY a JSON object: {"sql": "<one SELECT query>", "explanation": "<one sentence on the approach>"}.
- If the question cannot be answered from these tables, return {"sql": null, "explanation": "<why, and what the data does cover>"}.
- One read-only SELECT (CTEs allowed). No semicolons. DuckDB dialect.
- Join stations to show station_name. Round decimals sensibly. Order results meaningfully. LIMIT 200 unless the question needs every row.
- SCALES: columns ending in _pct are on a 0-100 scale (the 97% NEVI threshold is written 97, NEVER 0.97). Columns ending in _rate and port_utilization are 0-1 fractions.
- If a previous attempt failed, fix that SQL using the error message.`;var ANSWER_SYSTEM=`You write a short, factual answer to a question about Pennsylvania NEVI charging stations, using ONLY the query result provided.

Rules:
- 1-4 sentences of plain prose for a state DOT program manager. No markdown, no bullet points.
- Every number must come from the result rows. Do not invent or estimate numbers. Round sensibly.
- If the result has 0 rows, say only that the query returned no rows; do not draw conclusions from an empty result.
- If the result does not answer the question, say so plainly.
- Mention caveats from these rules only when relevant: data ends 2025-03-31; Tesla (Aston) reports no failed sessions; monthly_port uptime_pct ignores excluded outages.
Return ONLY JSON: {"answer": "<text>", "chart": {"type": "bar"|"line"|"none", "x": "<column>", "y": ["<numeric column>", ...]}}`;var json=(obj,status=200,headers={})=>new Response(JSON.stringify(obj),{status,headers:{"content-type":"application/json",...headers}});function cors(req,env){const origin=req.headers.get("origin")||"";const allowed=(env.ALLOWED_ORIGINS||"").split(",").map(s=>s.trim()).filter(Boolean);const ok=allowed.length===0||allowed.includes(origin);return ok?{"access-control-allow-origin":origin||"*","access-control-allow-methods":"POST, OPTIONS","access-control-allow-headers":"content-type, authorization","access-control-max-age":"86400",vary:"origin"}:null}function auth(req,env){const m=/^Bearer\s+([^:]+):([0-9a-f]{64})$/i.exec(req.headers.get("authorization")||"");if(!m)return null;let tokens={};try{tokens=JSON.parse(env.ACCESS_TOKENS||"{}")}catch{}const user=m[1].toLowerCase();return tokens[user]&&tokens[user]===m[2].toLowerCase()?user:null}function parseJSON(text){if(text&&typeof text==="object")return text;const s=String(text||"").replace(/```(?:json)?/g,"");const a=s.indexOf("{"),b=s.lastIndexOf("}");if(a<0||b<a)throw new Error("model did not return JSON");return JSON.parse(s.slice(a,b+1))}async function llm(env,system,user,maxTokens=900,opts={}){if(env.ANTHROPIC_API_KEY){const model2=env.ANTHROPIC_MODEL||"claude-sonnet-5-5";const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"content-type":"application/json","x-api-key":env.ANTHROPIC_API_KEY,"anthropic-version":"2023-06-01"},body:JSON.stringify({model:model2,max_tokens:maxTokens,temperature:0,system,messages:[{role:"user",content:user}]})});const j=await r.json();if(!r.ok)throw new Error(j?.error?.message||`Anthropic API ${r.status}`);return{text:j.content.map(c=>c.text||"").join(""),model:model2}}if(!env.AI)throw new Error("No model configured: add the Workers AI binding named AI, or an ANTHROPIC_API_KEY secret.");const model=opts.model&&WORKERS_AI_MODELS.includes(opts.model)?opts.model:env.WORKERS_AI_MODEL||DEFAULT_MODEL;const out=await env.AI.run(model,{messages:[{role:"system",content:system},{role:"user",content:user}],max_tokens:maxTokens,temperature:0});return{text:extractText(out),model:model.replace(/^@cf\//,"")}}function extractText(out){if(out==null)return"";if(typeof out==="string")return out;if(out.response!=null)return typeof out.response==="string"?out.response:JSON.stringify(out.response);if(out.choices?.[0]?.message?.content)return out.choices[0].message.content;if(out.output_text)return out.output_text;if(Array.isArray(out.output)){const parts=[];for(const o of out.output)for(const c of o.content||[])if(c.type==="output_text"||c.text)parts.push(c.text);if(parts.length)return parts.join("")}return JSON.stringify(out)}var src_default={async fetch(req,env){const h=cors(req,env);if(!h)return json({error:"Origin not allowed."},403);if(req.method==="OPTIONS")return new Response(null,{status:204,headers:h});const url=new URL(req.url);if(req.method==="GET"&&url.pathname==="/health")return json({ok:true,provider:env.ANTHROPIC_API_KEY?"anthropic":env.AI?"workers-ai":"none"},200,h);if(req.method!=="POST")return json({error:"Use POST."},405,h);const user=auth(req,env);if(!user)return json({error:"Sign in again: this session is not authorized to ask questions."},401,h);let body;try{body=await req.json()}catch{return json({error:"Request body must be JSON."},400,h)}const question=String(body.question||"").slice(0,600).trim();if(!question)return json({error:"Type a question first."},400,h);try{if(url.pathname==="/sql"){let prompt=`Question: ${question}`;if(body.previous_sql&&body.error)prompt+=`

Your previous SQL failed.
SQL:
${String(body.previous_sql).slice(0,4e3)}
Error:
${String(body.error).slice(0,1e3)}
Return corrected JSON.`;const{text,model}=await llm(env,SQL_SYSTEM,prompt,1200,{model:body.model});const out=parseJSON(text);console.log(JSON.stringify({user,kind:"sql",question,model,sql:out.sql}));return json({sql:out.sql?String(out.sql).trim().replace(/;\s*$/,""):null,explanation:out.explanation||"",model},200,h)}if(url.pathname==="/answer"){const columns=(body.columns||[]).slice(0,30);const rows=(body.rows||[]).slice(0,60);const prompt=`Question: ${question}

SQL that was run:
${String(body.sql||"").slice(0,4e3)}

Result: ${body.row_count??rows.length} rows${rows.length<(body.row_count??0)?` (first ${rows.length} shown)`:""}
Columns: ${JSON.stringify(columns)}
Rows: ${JSON.stringify(rows).slice(0,12e3)}`;const{text,model}=await llm(env,ANSWER_SYSTEM,prompt,800,{model:body.model});const out=parseJSON(text);console.log(JSON.stringify({user,kind:"answer",question,model}));return json({answer:String(out.answer||""),chart:out.chart||null,model},200,h)}return json({error:"Unknown endpoint."},404,h)}catch(e){console.log(JSON.stringify({user,error:e.message}));return json({error:`The language model could not answer: ${e.message}`},502,h)}}};export{src_default as default};
